@@ -0,0 +1,426 @@
+// Category configuration
+const CATEGORIES = {
+    food: { name: 'Food & Dining', icon: '🍔', color: '#f97316' },
+    transport: { name: 'Transportation', icon: '🚗', color: '#3b82f6' },
+    utilities: { name: 'Utilities', icon: '💡', color: '#eab308' },
+    entertainment: { name: 'Entertainment', icon: '🎬', color: '#ec4899' },
+    shopping: { name: 'Shopping', icon: '🛍️', color: '#8b5cf6' },
+    healthcare: { name: 'Healthcare', icon: '🏥', color: '#ef4444' },
+    education: { name: 'Education', icon: '📚', color: '#06b6d4' },
+    housing: { name: 'Housing', icon: '🏠', color: '#84cc16' },
+    savings: { name: 'Savings', icon: '💰', color: '#10b981' },
+    other: { name: 'Other', icon: '📦', color: '#6b7280' }
+};
+
+// Storage keys
+const STORAGE_KEYS = {
+    EXPENSES: 'budgetLogger_expenses',
+    AD_STATE: 'budgetLogger_adState'
+};
+
+// Ad configuration
+const AD_CONFIG = {
+    ENTRY_THRESHOLD: 4,      // Show ad every 4 entries
+    TIME_THRESHOLD: 600000   // Show ad every 10 minutes (in milliseconds)
+};
+
+// Application state
+let currentDate = new Date().toISOString().split('T')[0];
+let editingExpenseId = null;
+
+// DOM Elements
+const datePicker = document.getElementById('datePicker');
+const expenseForm = document.getElementById('expenseForm');
+const categorySelect = document.getElementById('category');
+const amountInput = document.getElementById('amount');
+const titleInput = document.getElementById('title');
+const submitBtn = document.getElementById('submitBtn');
+const pieChart = document.getElementById('pieChart');
+const chartPlaceholder = document.getElementById('chartPlaceholder');
+const legend = document.getElementById('legend');
+const totalAmount = document.getElementById('totalAmount');
+const expenseList = document.getElementById('expenseList');
+const adPopupOverlay = document.getElementById('adPopupOverlay');
+const adCloseBtn = document.getElementById('adCloseBtn');
+const editModalOverlay = document.getElementById('editModalOverlay');
+const editForm = document.getElementById('editForm');
+const editModalClose = document.getElementById('editModalClose');
+const editCancelBtn = document.getElementById('editCancelBtn');
+
+// Initialize application
+function init() {
+    // Set current date
+    datePicker.value = currentDate;
+    
+    // Load and render data
+    renderExpenses();
+    renderPieChart();
+    
+    // Initialize ad state
+    initAdState();
+    
+    // Set up event listeners
+    setupEventListeners();
+    
+    // Start ad timer
+    startAdTimer();
+}
+
+// Set up event listeners
+function setupEventListeners() {
+    datePicker.addEventListener('change', handleDateChange);
+    expenseForm.addEventListener('submit', handleAddExpense);
+    adCloseBtn.addEventListener('click', closeAdPopup);
+    adPopupOverlay.addEventListener('click', (e) => {
+        if (e.target === adPopupOverlay) closeAdPopup();
+    });
+    editModalClose.addEventListener('click', closeEditModal);
+    editCancelBtn.addEventListener('click', closeEditModal);
+    editModalOverlay.addEventListener('click', (e) => {
+        if (e.target === editModalOverlay) closeEditModal();
+    });
+    editForm.addEventListener('submit', handleEditExpense);
+}
+
+// Handle date change
+function handleDateChange(e) {
+    currentDate = e.target.value;
+    renderExpenses();
+    renderPieChart();
+}
+
+// Get all expenses from storage
+function getAllExpenses() {
+    const data = localStorage.getItem(STORAGE_KEYS.EXPENSES);
+    return data ? JSON.parse(data) : {};
+}
+
+// Save all expenses to storage
+function saveAllExpenses(expenses) {
+    localStorage.setItem(STORAGE_KEYS.EXPENSES, JSON.stringify(expenses));
+}
+
+// Get expenses for current date
+function getExpensesForDate(date) {
+    const allExpenses = getAllExpenses();
+    return allExpenses[date] || [];
+}
+
+// Save expenses for current date
+function saveExpensesForDate(date, expenses) {
+    const allExpenses = getAllExpenses();
+    allExpenses[date] = expenses;
+    saveAllExpenses(allExpenses);
+}
+
+// Generate unique ID
+function generateId() {
+    return Date.now().toString(36) + Math.random().toString(36).substr(2);
+}
+
+// Handle add expense
+function handleAddExpense(e) {
+    e.preventDefault();
+    
+    const expense = {
+        id: generateId(),
+        category: categorySelect.value,
+        amount: parseFloat(amountInput.value),
+        title: titleInput.value.trim(),
+        timestamp: Date.now()
+    };
+    
+    const expenses = getExpensesForDate(currentDate);
+    expenses.push(expense);
+    saveExpensesForDate(currentDate, expenses);
+    
+    // Reset form
+    expenseForm.reset();
+    
+    // Re-render
+    renderExpenses();
+    renderPieChart();
+    
+    // Check ad trigger
+    checkAdTrigger('entry');
+}
+
+// Handle edit expense
+function handleEditExpense(e) {
+    e.preventDefault();
+    
+    const id = document.getElementById('editId').value;
+    const expenses = getExpensesForDate(currentDate);
+    const index = expenses.findIndex(exp => exp.id === id);
+    
+    if (index !== -1) {
+        expenses[index] = {
+            ...expenses[index],
+            category: document.getElementById('editCategory').value,
+            amount: parseFloat(document.getElementById('editAmount').value),
+            title: document.getElementById('editTitle').value.trim()
+        };
+        saveExpensesForDate(currentDate, expenses);
+        renderExpenses();
+        renderPieChart();
+    }
+    
+    closeEditModal();
+}
+
+// Delete expense
+function deleteExpense(id) {
+    if (!confirm('Are you sure you want to delete this expense?')) return;
+    
+    const expenses = getExpensesForDate(currentDate);
+    const filtered = expenses.filter(exp => exp.id !== id);
+    saveExpensesForDate(currentDate, filtered);
+    
+    renderExpenses();
+    renderPieChart();
+}
+
+// Open edit modal
+function openEditModal(id) {
+    const expenses = getExpensesForDate(currentDate);
+    const expense = expenses.find(exp => exp.id === id);
+    
+    if (expense) {
+        document.getElementById('editId').value = expense.id;
+        document.getElementById('editCategory').value = expense.category;
+        document.getElementById('editAmount').value = expense.amount;
+        document.getElementById('editTitle').value = expense.title;
+        editModalOverlay.classList.add('active');
+    }
+}
+
+// Close edit modal
+function closeEditModal() {
+    editModalOverlay.classList.remove('active');
+    editForm.reset();
+}
+
+// Render expenses list
+function renderExpenses() {
+    const expenses = getExpensesForDate(currentDate);
+    
+    if (expenses.length === 0) {
+        expenseList.innerHTML = '<p class="no-expenses">No expenses for this date</p>';
+        return;
+    }
+    
+    // Sort by timestamp descending (newest first)
+    expenses.sort((a, b) => b.timestamp - a.timestamp);
+    
+    expenseList.innerHTML = expenses.map(expense => {
+        const cat = CATEGORIES[expense.category];
+        return `
+            <div class="expense-item" data-category="${expense.category}">
+                <span class="expense-category-icon">${cat.icon}</span>
+                <div class="expense-details">
+                    <div class="expense-title">${escapeHtml(expense.title)}</div>
+                    <div class="expense-category-name">${cat.name}</div>
+                </div>
+                <div class="expense-amount">$${expense.amount.toFixed(2)}</div>
+                <div class="expense-actions">
+                    <button class="btn-icon btn-edit" onclick="openEditModal('${expense.id}')" title="Edit">✏️</button>
+                    <button class="btn-icon btn-delete" onclick="deleteExpense('${expense.id}')" title="Delete">🗑️</button>
+                </div>
+            </div>
+        `;
+    }).join('');
+}
+
+// Escape HTML to prevent XSS
+function escapeHtml(text) {
+    const div = document.createElement('div');
+    div.textContent = text;
+    return div.innerHTML;
+}
+
+// Render pie chart
+function renderPieChart() {
+    const expenses = getExpensesForDate(currentDate);
+    const ctx = pieChart.getContext('2d');
+    
+    // Clear canvas
+    ctx.clearRect(0, 0, pieChart.width, pieChart.height);
+    
+    if (expenses.length === 0) {
+        chartPlaceholder.classList.remove('hidden');
+        legend.innerHTML = '';
+        totalAmount.textContent = '$0.00';
+        return;
+    }
+    
+    chartPlaceholder.classList.add('hidden');
+    
+    // Calculate totals by category
+    const categoryTotals = {};
+    let total = 0;
+    
+    expenses.forEach(expense => {
+        if (!categoryTotals[expense.category]) {
+            categoryTotals[expense.category] = 0;
+        }
+        categoryTotals[expense.category] += expense.amount;
+        total += expense.amount;
+    });
+    
+    // Update total display
+    totalAmount.textContent = `$${total.toFixed(2)}`;
+    
+    // Prepare data for pie chart
+    const data = Object.entries(categoryTotals).map(([category, amount]) => ({
+        category,
+        amount,
+        percentage: (amount / total) * 100,
+        color: CATEGORIES[category].color
+    }));
+    
+    // Sort by amount descending
+    data.sort((a, b) => b.amount - a.amount);
+    
+    // Draw pie chart
+    drawPieChart(ctx, data);
+    
+    // Render legend
+    renderLegend(data);
+}
+
+// Draw pie chart on canvas
+function drawPieChart(ctx, data) {
+    const canvas = ctx.canvas;
+    const size = Math.min(canvas.offsetWidth, canvas.offsetHeight);
+    
+    // Set canvas size for retina displays
+    const dpr = window.devicePixelRatio || 1;
+    canvas.width = size * dpr;
+    canvas.height = size * dpr;
+    ctx.scale(dpr, dpr);
+    
+    const centerX = size / 2;
+    const centerY = size / 2;
+    const radius = (size / 2) - 10;
+    
+    let startAngle = -Math.PI / 2; // Start from top
+    
+    data.forEach(item => {
+        const sliceAngle = (item.percentage / 100) * 2 * Math.PI;
+        
+        ctx.beginPath();
+        ctx.moveTo(centerX, centerY);
+        ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
+        ctx.closePath();
+        
+        ctx.fillStyle = item.color;
+        ctx.fill();
+        
+        // Add white border between slices
+        ctx.strokeStyle = '#ffffff';
+        ctx.lineWidth = 2;
+        ctx.stroke();
+        
+        startAngle += sliceAngle;
+    });
+    
+    // Draw center circle for donut effect
+    ctx.beginPath();
+    ctx.arc(centerX, centerY, radius * 0.5, 0, 2 * Math.PI);
+    ctx.fillStyle = getComputedStyle(document.body).getPropertyValue('--card-bg').trim() || '#ffffff';
+    ctx.fill();
+}
+
+// Render legend
+function renderLegend(data) {
+    legend.innerHTML = data.map(item => {
+        const cat = CATEGORIES[item.category];
+        return `
+            <div class="legend-item">
+                <span class="legend-color" style="background-color: ${item.color}"></span>
+                <span class="legend-text">${cat.icon} ${cat.name}</span>
+                <span class="legend-percentage">${item.percentage.toFixed(1)}%</span>
+            </div>
+        `;
+    }).join('');
+}
+
+// Ad State Management
+function getAdState() {
+    const data = localStorage.getItem(STORAGE_KEYS.AD_STATE);
+    return data ? JSON.parse(data) : {
+        entryCount: 0,
+        lastAdTime: Date.now(),
+        totalEntries: 0
+    };
+}
+
+function saveAdState(state) {
+    localStorage.setItem(STORAGE_KEYS.AD_STATE, JSON.stringify(state));
+}
+
+function initAdState() {
+    const state = getAdState();
+    if (!state.lastAdTime) {
+        state.lastAdTime = Date.now();
+        saveAdState(state);
+    }
+}
+
+function checkAdTrigger(type) {
+    const state = getAdState();
+    
+    if (type === 'entry') {
+        state.entryCount++;
+        state.totalEntries++;
+        saveAdState(state);
+        
+        if (state.entryCount >= AD_CONFIG.ENTRY_THRESHOLD) {
+            showAdPopup();
+            state.entryCount = 0;
+            state.lastAdTime = Date.now();
+            saveAdState(state);
+        }
+    }
+}
+
+function checkTimeBasedAd() {
+    const state = getAdState();
+    const now = Date.now();
+    
+    if (now - state.lastAdTime >= AD_CONFIG.TIME_THRESHOLD) {
+        showAdPopup();
+        state.lastAdTime = now;
+        saveAdState(state);
+    }
+}
+
+function startAdTimer() {
+    // Check every minute
+    setInterval(checkTimeBasedAd, 60000);
+}
+
+function showAdPopup() {
+    adPopupOverlay.classList.add('active');
+    
+    // Here you can initialize Google Ads
+    // Example: load Google Ads script and render ad in #googleAdSlot
+    // window.adsbygoogle = window.adsbygoogle || [];
+    // window.adsbygoogle.push({});
+}
+
+function closeAdPopup() {
+    adPopupOverlay.classList.remove('active');
+}
+
+// Handle window resize for chart
+let resizeTimeout;
+window.addEventListener('resize', () => {
+    clearTimeout(resizeTimeout);
+    resizeTimeout = setTimeout(() => {
+        renderPieChart();
+    }, 250);
+});
+
+// Initialize the app
+document.addEventListener('DOMContentLoaded', init);
