+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Budget Logger</title>
+    <link rel="stylesheet" href="styles.css">
+</head>
+<body>
+    <div class="container">
+        <header>
+            <h1>💰 Budget Logger</h1>
+            <div class="date-picker-container">
+                <label for="datePicker">Select Date:</label>
+                <input type="date" id="datePicker">
+            </div>
+        </header>
+
+        <main>
+            <!-- Expense Entry Form -->
+            <section class="expense-form-section">
+                <h2>Add Expense</h2>
+                <form id="expenseForm">
+                    <div class="form-group">
+                        <label for="category">Category</label>
+                        <select id="category" required>
+                            <option value="">Select Category</option>
+                            <option value="food">🍔 Food & Dining</option>
+                            <option value="transport">🚗 Transportation</option>
+                            <option value="utilities">💡 Utilities</option>
+                            <option value="entertainment">🎬 Entertainment</option>
+                            <option value="shopping">🛍️ Shopping</option>
+                            <option value="healthcare">🏥 Healthcare</option>
+                            <option value="education">📚 Education</option>
+                            <option value="housing">🏠 Housing</option>
+                            <option value="savings">💰 Savings</option>
+                            <option value="other">📦 Other</option>
+                        </select>
+                    </div>
+                    <div class="form-group">
+                        <label for="amount">Amount ($)</label>
+                        <input type="number" id="amount" step="0.01" min="0.01" placeholder="0.00" required>
+                    </div>
+                    <div class="form-group">
+                        <label for="title">Title</label>
+                        <input type="text" id="title" placeholder="e.g., Grocery shopping" required>
+                    </div>
+                    <button type="submit" class="btn-primary" id="submitBtn">Add Expense</button>
+                </form>
+            </section>
+
+            <!-- Pie Chart Section -->
+            <section class="chart-section">
+                <h2>Expense Breakdown</h2>
+                <div class="chart-container">
+                    <canvas id="pieChart"></canvas>
+                    <div class="chart-placeholder" id="chartPlaceholder">
+                        <p>No expenses recorded for this date</p>
+                    </div>
+                </div>
+                <div class="legend" id="legend"></div>
+                <div class="total-display">
+                    <span>Total:</span>
+                    <span id="totalAmount">$0.00</span>
+                </div>
+            </section>
+
+            <!-- Expense List Section -->
+            <section class="expense-list-section">
+                <h2>Expenses</h2>
+                <div class="expense-list" id="expenseList">
+                    <p class="no-expenses">No expenses for this date</p>
+                </div>
+            </section>
+        </main>
+    </div>
+
+    <!-- Ad Popup Modal -->
+    <div class="ad-popup-overlay" id="adPopupOverlay">
+        <div class="ad-popup">
+            <button class="ad-close-btn" id="adCloseBtn">&times;</button>
+            <div class="ad-content" id="adContent">
+                <!-- Google Ads will be inserted here -->
+                <p class="ad-placeholder">Advertisement Space</p>
+                <div id="googleAdSlot">
+                    <!-- Your Google Ads code goes here -->
+                </div>
+            </div>
+        </div>
+    </div>
+
+    <!-- Edit Modal -->
+    <div class="modal-overlay" id="editModalOverlay">
+        <div class="modal">
+            <div class="modal-header">
+                <h3>Edit Expense</h3>
+                <button class="modal-close-btn" id="editModalClose">&times;</button>
+            </div>
+            <form id="editForm">
+                <input type="hidden" id="editId">
+                <div class="form-group">
+                    <label for="editCategory">Category</label>
+                    <select id="editCategory" required>
+                        <option value="food">🍔 Food & Dining</option>
+                        <option value="transport">🚗 Transportation</option>
+                        <option value="utilities">💡 Utilities</option>
+                        <option value="entertainment">🎬 Entertainment</option>
+                        <option value="shopping">🛍️ Shopping</option>
+                        <option value="healthcare">🏥 Healthcare</option>
+                        <option value="education">📚 Education</option>
+                        <option value="housing">🏠 Housing</option>
+                        <option value="savings">💰 Savings</option>
+                        <option value="other">📦 Other</option>
+                    </select>
+                </div>
+                <div class="form-group">
+                    <label for="editAmount">Amount ($)</label>
+                    <input type="number" id="editAmount" step="0.01" min="0.01" required>
+                </div>
+                <div class="form-group">
+                    <label for="editTitle">Title</label>
+                    <input type="text" id="editTitle" required>
+                </div>
+                <div class="modal-actions">
+                    <button type="button" class="btn-secondary" id="editCancelBtn">Cancel</button>
+                    <button type="submit" class="btn-primary">Save Changes</button>
+                </div>
+            </form>
+        </div>
+    </div>
+
+    <script src="app.js"></script>
+</body>
+</html>
