+++ b/examples/BasicDiagnostics/BasicDiagnostics.ino
@@ -0,0 +1,71 @@
+#include <Arduino.h>
+#include <string.h>
+#include <wcx.h>
+
+static uint8_t serialStorage[64];
+static wcx_ring_buffer_t serialRing;
+static wcx_stats_t stats;
+static wcx_debounce_t button;
+
+static void enqueueMessage(const char *text)
+{
+    wcx_ring_buffer_write(&serialRing, (const uint8_t *)text, strlen(text));
+}
+
+void setup()
+{
+    Serial.begin(115200);
+    pinMode(LED_BUILTIN, OUTPUT);
+    pinMode(2, INPUT_PULLUP);
+
+    wcx_ring_buffer_init(&serialRing, serialStorage, sizeof(serialStorage));
+    wcx_stats_init(&stats);
+    wcx_debounce_init(&button, false, 25);
+
+    enqueueMessage("WCX diagnostics ready\n");
+}
+
+void loop()
+{
+    static uint32_t lastReport = 0;
+
+    const bool pressed = !digitalRead(2);
+    const int sample = analogRead(A0);
+    uint8_t value;
+
+    wcx_stats_update(&stats, (float)sample);
+    wcx_debounce_update(&button, pressed, millis());
+
+    if (wcx_debounce_rose(&button))
+    {
+        enqueueMessage("Button pressed\n");
+        digitalWrite(LED_BUILTIN, HIGH);
+    }
+
+    if (wcx_debounce_fell(&button))
+    {
+        enqueueMessage("Button released\n");
+        digitalWrite(LED_BUILTIN, LOW);
+    }
+
+    if (wcx_time_reached(millis(), lastReport + 1000))
+    {
+        const uint16_t crc = wcx_crc16_ccitt((const uint8_t *)&sample, sizeof(sample), 0xFFFF);
+        Serial.print("samples=");
+        Serial.print(wcx_stats_count(&stats));
+        Serial.print(" mean=");
+        Serial.print(wcx_stats_mean(&stats), 2);
+        Serial.print(" min=");
+        Serial.print(wcx_stats_min(&stats), 2);
+        Serial.print(" max=");
+        Serial.print(wcx_stats_max(&stats), 2);
+        Serial.print(" crc16=0x");
+        Serial.println(crc, HEX);
+        lastReport = millis();
+    }
+
+    while (wcx_ring_buffer_pop(&serialRing, &value))
+    {
+        Serial.write(value);
+    }
+}
diff --git a/examples/ControlLoopDemo/ControlLoopDemo.ino b/examples/ControlLoopDemo/ControlLoopDemo.ino
new file mode 100644
index 0000000..7cfdbd1
--- /dev/null
+++ b/examples/ControlLoopDemo/ControlLoopDemo.ino
@@ -0,0 +1,45 @@
+#include <Arduino.h>
+#include <wcx.h>
+
+static float averageStorage[8];
+static wcx_moving_average_t averageFilter;
+static wcx_ema_filter_t emaFilter;
+static wcx_pid_t controller;
+
+void setup()
+{
+    Serial.begin(115200);
+    pinMode(LED_BUILTIN, OUTPUT);
+    pinMode(9, OUTPUT);
+
+    wcx_moving_average_init(&averageFilter, averageStorage, WCX_ARRAY_SIZE(averageStorage));
+    wcx_ema_init(&emaFilter, 0.15f, 0.0f, false);
+    wcx_pid_init(&controller, 0.7f, 0.4f, 0.05f, 0.0f, 255.0f);
+}
+
+void loop()
+{
+    static uint32_t lastTick = 0;
+    const float dt = 0.02f;
+    const float setpoint = 650.0f;
+    const float sensorRaw = (float)analogRead(A0);
+    const float filtered = wcx_ema_update(&emaFilter, wcx_moving_average_update(&averageFilter, sensorRaw));
+    const float output = wcx_pid_compute(&controller, setpoint, filtered, dt);
+
+    if (!wcx_time_reached(millis(), lastTick + 20))
+    {
+        return;
+    }
+
+    analogWrite(9, (int)output);
+    digitalWrite(LED_BUILTIN, output > 127.0f ? HIGH : LOW);
+
+    Serial.print("raw=");
+    Serial.print(sensorRaw, 2);
+    Serial.print(" filtered=");
+    Serial.print(filtered, 2);
+    Serial.print(" output=");
+    Serial.println(output, 2);
+
+    lastTick = millis();
+}
