+#ifndef WCX_COMMON_H
+#define WCX_COMMON_H
+
+#include <stdbool.h>
+#include <stddef.h>
+#include <stdint.h>
+
+#ifdef __cplusplus
+extern "C"
+{
+#endif
+
+#define WCX_ARRAY_SIZE(array) (sizeof(array) / sizeof((array)[0]))
+#define WCX_MIN(a, b) ((a) < (b) ? (a) : (b))
+#define WCX_MAX(a, b) ((a) > (b) ? (a) : (b))
